terraform {
  required_version = ">= 1.5.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.63.0, < 7.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = local.tags
  }
}

variable "aws_region" {
  type        = string
  description = "AWS Region selected by the immutable Architecture Document."
  default     = "us-east-1"
}

variable "event_eventbridge_scheduled_artifact_path" {
  type        = string
  description = "Stable relative package output produced by the separate Prompt 32A workload builder."
  default     = "../application/artifacts/workload_event_eventbridge_scheduled/function.zip"
  validation {
    condition     = can(regex("^\\.\\.?/", var.event_eventbridge_scheduled_artifact_path))
    error_message = "Package path must be repository-relative and begin with ./ or ../; absolute machine paths are forbidden."
  }
}

variable "stage" {
  type        = string
  description = "Architecture variable stage."
  default     = "test"
}

locals {
  tags = {
    CloudMarkupArchitecture     = "architecture_event_eventbridge_scheduled"
    CloudMarkupRevision         = "revision_event_eventbridge_scheduled_1"
    CloudMarkupSolutionRevision = "solution_notes_revision_1"
    ManagedBy                   = "CloudMarkup"
  }
}

resource "aws_lambda_function" "event_eventbridge_scheduled" {
  function_name                  = "event_eventbridge_scheduled"
  description                    = "CloudMarkup notes-API workload."
  role                           = aws_iam_role.notes_role.arn
  handler                        = "index.handler"
  runtime                        = "nodejs24.x"
  architectures                  = ["arm64"]
  memory_size                    = 256
  reserved_concurrent_executions = 10
  timeout                        = 30
  filename                       = var.event_eventbridge_scheduled_artifact_path
  source_code_hash               = filebase64sha256(var.event_eventbridge_scheduled_artifact_path)
  tracing_config {
    mode = "Active"
  }
  environment {
    variables = {
      "APP_STAGE" = var.stage
    }
  }
  tags = local.tags
}

data "aws_iam_policy_document" "event_logs_policy_eventbridge_scheduled" {
  statement {
    sid       = "eventlogspolicyeventbridgescheduled"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = [format("%s:*", aws_cloudwatch_log_group.event_logs_eventbridge_scheduled.arn)]
  }
}

data "aws_iam_policy_document" "trust_policy" {
  statement {
    sid     = "trustpolicy"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "event_logs_policy_eventbridge_scheduled" {
  name   = "event_logs_policy_eventbridge_scheduled"
  role   = aws_iam_role.notes_role.name
  policy = data.aws_iam_policy_document.event_logs_policy_eventbridge_scheduled.json
}

resource "aws_lambda_permission" "event_permission" {
  statement_id  = "eventpermission"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.event_eventbridge_scheduled.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.hourly.arn
}

data "aws_cloudwatch_event_bus" "default_bus" {
  name = "default"
}

resource "aws_cloudwatch_event_rule" "hourly" {
  name                = "hourly-processing"
  state               = "ENABLED"
  event_bus_name      = data.aws_cloudwatch_event_bus.default_bus.name
  schedule_expression = "rate(1 hour)"
  tags                = local.tags
}

resource "aws_cloudwatch_event_target" "scheduled_target" {
  rule           = aws_cloudwatch_event_rule.hourly.name
  event_bus_name = data.aws_cloudwatch_event_bus.default_bus.name
  target_id      = "scheduled-handler"
  arn            = aws_lambda_function.event_eventbridge_scheduled.arn
  retry_policy {
    maximum_event_age_in_seconds = 3600
    maximum_retry_attempts       = 10
  }
}

resource "aws_cloudwatch_log_group" "event_logs_eventbridge_scheduled" {
  name              = "/aws/lambda/notes_handler"
  log_group_class   = "STANDARD"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}
